package main
import("image";"image/color";"image/draw";"image/jpeg";"math";"os";"path/filepath";"fmt")
func main(){ out:=os.Args[1]; colors:=[]color.RGBA{{220,35,45,255},{25,80,225,255},{25,155,75,255},{240,195,25,255},{140,50,185,255},{235,115,25,255}}; for n,c:=range colors {img:=image.NewRGBA(image.Rect(0,0,640,360));draw.Draw(img,img.Bounds(),&image.Uniform{color.RGBA{245,245,240,255}},image.Point{},draw.Src);for y:=0;y<360;y++{for x:=0;x<640;x++{dx,dy:=float64(x-320),float64(y-180);inside:=false;switch n {case 0:inside=dx*dx+dy*dy<90*90;case 1:inside=x>=225&&x<415&&y>=85&&y<275;case 2:inside=y>=60&&y<=300&&math.Abs(dx)<=float64(y-60)/2;case 3:a:=math.Atan2(dy,dx)+math.Pi/2;sector:=math.Mod(a+math.Pi*4,2*math.Pi/5);r:=50.0;if sector<math.Pi/5{r=50+65*(1-sector/(math.Pi/5))}else{r=50+65*((sector-math.Pi/5)/(math.Pi/5))};inside=math.Hypot(dx,dy)<r;case 4:inside=(x-230)*(x-230)+(y-180)*(y-180)<65*65||(x-410)*(x-410)+(y-180)*(y-180)<65*65;case 5:inside=x>=150&&x<490&&y>=130&&y<230};if inside{img.SetRGBA(x,y,c)}}};f,e:=os.Create(filepath.Join(out,fmt.Sprintf("scene-%02d.jpg",n)));if e!=nil{panic(e)};if e=jpeg.Encode(f,img,&jpeg.Options{Quality:92});e!=nil{panic(e)};f.Close()}}
